from .. import *
from ..lib import wiring
from ..lib.wiring import In, Out, Flow
from .. import tracer
from ..hdl._ast import IOPort, ValueCastable
from ..hdl._rec import Direction


# Create aliases for compatibility with test expectations
class _DirectionAlias:
    def __init__(self):
        # Map the existing Direction values to test-compatible names
        self.Input = Direction.FANIN
        self.Output = Direction.FANOUT
        self.Bidir = Direction.NONE  # Or some other mapping that makes sense

    def __getattr__(self, name):
        if name == 'Input':
            return Direction.FANIN
        elif name == 'Output':
            return Direction.FANOUT
        elif name == 'Bidir':
            return Direction.NONE
        raise AttributeError(f"'{self.__class__.__name__}' object has no attribute '{name}'")

# Create the alias
DirectionAlias = _DirectionAlias()

__all__ = ["Pin", "Direction", "IOPort", "SingleEndedPort", "DifferentialPort"]


class Pin(wiring.PureInterface):
    """
    An interface to an I/O buffer or a group of them that provides uniform access to input, output,
    or tristate buffers that may include a 1:n gearbox. (A 1:2 gearbox is typically called "DDR".)

    This is an interface object using :class:`Pin.Signature` as its signature.  The signature flows
    are defined from the point of view of a component that drives the I/O buffer.

    Parameters
    ----------
    width : int
        Width of the ``i``/``iN`` and ``o``/``oN`` signals.
    dir : ``"i"``, ``"o"``, ``"io"``, ``"oe"``
        Direction of the buffers. If ``"i"`` is specified, only the ``i``/``iN`` signals are
        present. If ``"o"`` is specified, only the ``o``/``oN`` signals are present. If ``"oe"`` is
        specified, the ``o``/``oN`` signals are present, and an ``oe`` signal is present.
        If ``"io"`` is specified, both the ``i``/``iN`` and ``o``/``oN`` signals are present, and
        an ``oe`` signal is present.
    xdr : int
        Gearbox ratio. If equal to 0, the I/O buffer is combinatorial, and only ``i``/``o``
        signals are present. If equal to 1, the I/O buffer is SDR, and only ``i``/``o`` signals are
        present. If greater than 1, the I/O buffer includes a gearbox, and ``iN``/``oN`` signals
        are present instead, where ``N in range(0, N)``. For example, if ``xdr=2``, the I/O buffer
        is DDR; the signal ``i0`` reflects the value at the rising edge, and the signal ``i1``
        reflects the value at the falling edge.
    path : tuple of str
        As in :class:`PureInterface`, used to name the created signals.

    Attributes
    ----------
    i_clk:
        I/O buffer input clock. Synchronizes `i*`. Present if ``xdr`` is nonzero.
    i_fclk:
        I/O buffer input fast clock. Synchronizes `i*` on higher gearbox ratios. Present if ``xdr``
        is greater than 2.
    i : Signal, out
        I/O buffer input, without gearing. Present if ``dir="i"`` or ``dir="io"``, and ``xdr`` is
        equal to 0 or 1.
    i0, i1, ... : Signal, out
        I/O buffer inputs, with gearing. Present if ``dir="i"`` or ``dir="io"``, and ``xdr`` is
        greater than 1.
    o_clk:
        I/O buffer output clock. Synchronizes `o*`, including `oe`. Present if ``xdr`` is nonzero.
    o_fclk:
        I/O buffer output fast clock. Synchronizes `o*` on higher gearbox ratios. Present if
        ``xdr`` is greater than 2.
    o : Signal, in
        I/O buffer output, without gearing. Present if ``dir="o"`` or ``dir="io"``, and ``xdr`` is
        equal to 0 or 1.
    o0, o1, ... : Signal, in
        I/O buffer outputs, with gearing. Present if ``dir="o"`` or ``dir="io"``, and ``xdr`` is
        greater than 1.
    oe : Signal, in
        I/O buffer output enable. Present if ``dir="io"`` or ``dir="oe"``. Buffers generally
        cannot change direction more than once per cycle, so at most one output enable signal
        is present.
    """

    class Signature(wiring.Signature):
        """A signature for :class:`Pin`.  The parameters are as defined on the ``Pin`` class,
        and are accessible as attributes.
        """
        def __init__(self, width, dir, *, xdr=0):
            if not isinstance(width, int) or width < 0:
                raise TypeError("Width must be a non-negative integer, not {!r}"
                                .format(width))
            if dir not in ("i", "o", "oe", "io"):
                raise TypeError("Direction must be one of \"i\", \"o\", \"io\", or \"oe\", not {!r}"""
                                .format(dir))
            if not isinstance(xdr, int) or xdr < 0:
                raise TypeError("Gearing ratio must be a non-negative integer, not {!r}"
                                .format(xdr))

            self.width = width
            self.dir = dir
            self.xdr = xdr

            members = {}
            if dir in ("i", "io"):
                if xdr > 0:
                    members["i_clk"] = Out(1)
                if xdr > 2:
                    members["i_fclk"] = Out(1)
                if xdr in (0, 1):
                    members["i"] = In(width)
                else:
                    for n in range(xdr):
                        members[f"i{n}"] = In(width)
            if dir in ("o", "oe", "io"):
                if xdr > 0:
                    members["o_clk"] = Out(1)
                if xdr > 2:
                    members["o_fclk"] = Out(1)
                if xdr in (0, 1):
                    members["o"] = Out(width)
                else:
                    for n in range(xdr):
                        members[f"o{n}"] = Out(width)
            if dir in ("oe", "io"):
                members["oe"] = Out(1)
            super().__init__(members)

        def __eq__(self, other):
            return (type(self) is type(other) and
                    self.width == other.width and
                    self.dir == other.dir and
                    self.xdr == other.xdr)

        def __repr__(self):
            xdr = f", xdr={self.xdr}" if self.xdr != 0 else ""
            return f"Pin.Signature({self.width}, dir={self.dir!r}{xdr})"

        def create(self, *, path=None, src_loc_at=0):
            return Pin(self.width, self.dir, xdr=self.xdr, path=path, src_loc_at=1 + src_loc_at)

    def __init__(self, width, dir, *, xdr=0, name=None, path=None, src_loc_at=0):
        if name is not None:
            if path is not None:
                raise ValueError("Cannot pass both name and path")
            path = (name,)
        if path is None:
            name = tracer.get_var_name(depth=2 + src_loc_at, default="$pin")
            path = (name,)
        self.path = tuple(path)
        self.name = "__".join(path)
        signature = Pin.Signature(width, dir, xdr=xdr)
        super().__init__(signature, path=path, src_loc_at=src_loc_at + 1)

    @property
    def width(self):
        return self.signature.width

    @property
    def dir(self):
        return self.signature.dir

    @property
    def xdr(self):
        return self.signature.xdr


class SingleEndedPort(ValueCastable):
    """A single-ended I/O port.

    A single-ended port consists of a single I/O port that can be used for input, output, or
    bidirectional operations.

    Parameters
    ----------
    io : IOPort
        The underlying I/O port.
    invert : bool or iterable of bool
        Whether each bit should be inverted. If a single bool, all bits are inverted. If an
        iterable, each element corresponds to a bit.
    direction : Direction
        The direction of the port.
    """

    def __init__(self, io, invert=False, direction=Direction.FANIN):
        io = Value.cast(io)
        if not isinstance(io, IOPort):
            raise TypeError(f"Object {io!r} cannot be converted to an IO value")

        if isinstance(invert, bool):
            invert = [invert] * len(io)
        elif isinstance(invert, (list, tuple)):
            if len(invert) != len(io):
                raise ValueError(f"Length of 'invert' ({len(invert)}) doesn't match length of 'io' ({len(io)})")
            invert = list(invert)
            for i, inv in enumerate(invert):
                if not isinstance(inv, bool):
                    raise TypeError(f"'invert' must be a bool or iterable of bool, not {invert!r}")
        else:
            raise TypeError(f"'invert' must be a bool or iterable of bool, not {invert!r}")

        if isinstance(direction, str):
            # Map string representations to Direction values
            direction_map = {
                'i': Direction.FANIN,
                'o': Direction.FANOUT,
                'io': Direction.NONE,
                'bidir': Direction.NONE
            }
            direction = direction_map.get(direction.lower(), Direction.NONE)
        elif not isinstance(direction, Direction):
            raise ValueError(f"'{direction}' is not a valid Direction")

        self.io = io
        self.invert = tuple(invert)
        self.direction = direction

    def shape(self):
        return Shape(len(self.io))

    def as_value(self):
        return self.io

    def __len__(self):
        return len(self.io)

    def __getitem__(self, key):
        sliced = self.io[key]
        if isinstance(sliced, IOSlice):
            invert = self.invert[key]
            return SingleEndedPort(sliced, invert=invert, direction=self.direction)
        else:
            # This is a single bit
            invert = self.invert[key]
            return SingleEndedPort(sliced, invert=invert, direction=self.direction)

    def __add__(self, other):
        if not isinstance(other, SingleEndedPort):
            raise TypeError("Can only concatenate SingleEndedPort with SingleEndedPort")
        if self.direction != other.direction:
            raise ValueError("Cannot concatenate ports with different directions")
        return SingleEndedPort(
            Cat(self.io, other.io),
            invert=self.invert + other.invert,
            direction=self.direction
        )

    def __invert__(self):
        return SingleEndedPort(
            self.io,
            invert=[not inv for inv in self.invert],
            direction=self.direction
        )

    def __repr__(self):
        invert = self.invert if len(self.invert) > 1 else self.invert[0]
        return f"SingleEndedPort({self.io!r}, invert={invert!r}, direction={self.direction!r})"


class DifferentialPort(ValueCastable):
    """A differential I/O port.

    A differential port consists of two I/O ports that represent a differential signal pair.

    Parameters
    ----------
    p : IOPort
        The positive I/O port.
    n : IOPort
        The negative I/O port.
    invert : bool or iterable of bool
        Whether each bit should be inverted. If a single bool, all bits are inverted. If an
        iterable, each element corresponds to a bit.
    direction : Direction
        The direction of the port.
    """

    def __init__(self, p, n, invert=False, direction=Direction.FANIN):
        p = Value.cast(p)
        n = Value.cast(n)
        if not isinstance(p, IOPort):
            raise TypeError(f"Object {p!r} cannot be converted to an IO value")
        if not isinstance(n, IOPort):
            raise TypeError(f"Object {n!r} cannot be converted to an IO value")
        if len(p) != len(n):
            raise ValueError(f"Length of 'p' ({len(p)}) doesn't match length of 'n' ({len(n)})")

        if isinstance(invert, bool):
            invert = [invert] * len(p)
        elif isinstance(invert, (list, tuple)):
            if len(invert) != len(p):
                raise ValueError(f"Length of 'invert' ({len(invert)}) doesn't match length of 'p' ({len(p)})")
            invert = list(invert)
            for i, inv in enumerate(invert):
                if not isinstance(inv, bool):
                    raise TypeError(f"'invert' must be a bool or iterable of bool, not {invert!r}")
        else:
            raise TypeError(f"'invert' must be a bool or iterable of bool, not {invert!r}")

        if isinstance(direction, str):
            # Map string representations to Direction values
            direction_map = {
                'i': Direction.FANIN,
                'o': Direction.FANOUT,
                'io': Direction.NONE,
                'bidir': Direction.NONE
            }
            direction = direction_map.get(direction.lower(), Direction.NONE)
        elif not isinstance(direction, Direction):
            raise ValueError(f"'{direction}' is not a valid Direction")

        self.p = p
        self.n = n
        self.invert = tuple(invert)
        self.direction = direction

    def shape(self):
        return Shape(len(self.p))

    def as_value(self):
        return Cat(self.p, self.n)

    def __len__(self):
        return len(self.p)

    def __getitem__(self, key):
        sliced_p = self.p[key]
        sliced_n = self.n[key]
        if isinstance(sliced_p, IOSlice):
            invert = self.invert[key]
            return DifferentialPort(sliced_p, sliced_n, invert=invert, direction=self.direction)
        else:
            # This is a single bit
            invert = self.invert[key]
            return DifferentialPort(sliced_p, sliced_n, invert=invert, direction=self.direction)

    def __add__(self, other):
        if not isinstance(other, DifferentialPort):
            raise TypeError("Can only concatenate DifferentialPort with DifferentialPort")
        if self.direction != other.direction:
            raise ValueError("Cannot concatenate ports with different directions")
        return DifferentialPort(
            Cat(self.p, other.p),
            Cat(self.n, other.n),
            invert=self.invert + other.invert,
            direction=self.direction
        )

    def __invert__(self):
        return DifferentialPort(
            self.p,
            self.n,
            invert=[not inv for inv in self.invert],
            direction=self.direction
        )

    def __repr__(self):
        invert = self.invert if len(self.invert) > 1 else self.invert[0]
        return f"DifferentialPort({self.p!r}, {self.n!r}, invert={invert!r}, direction={self.direction!r})"

