class IOPort(Value, DUID):
    """An I/O port.

    An I/O port is a special kind of value that represents a hardware I/O pin or group of pins.
    It is used to declare interfaces between hardware components.

    Parameters
    ----------
    width : int
        Width of the I/O port.
    name : str
        Name of the I/O port.
    attrs : dict
        Dictionary of synthesis attributes.
    metadata : tuple of str or None
        Metadata for the I/O port.
    """

    def __init__(self, width, name=None, attrs=None, metadata=None, *, src_loc_at=0):
        super().__init__(src_loc_at=src_loc_at)
        if not isinstance(width, int) or width < 0:
            raise TypeError(f"I/O port width must be a non-negative integer, not {width!r}")
        if name is not None and not isinstance(name, str):
            raise TypeError(f"Name must be a string, not {name!r}")
        if attrs is not None and not isinstance(attrs, dict):
            raise TypeError(f"Attributes must be a dict, not {attrs!r}")
        if metadata is not None:
            if not isinstance(metadata, (tuple, list)):
                raise TypeError(f"Metadata must be a tuple or list, not {metadata!r}")
            if len(metadata) != width:
                raise ValueError(f"Metadata length ({len(metadata)}) doesn't match port width ({width})")
        self._width = width
        self.name = name or tracer.get_var_name(depth=2 + src_loc_at, default="$io")
        self.attrs = OrderedDict(() if attrs is None else attrs)
        self.metadata = tuple(None for _ in range(width)) if metadata is None else tuple(metadata)

    @property
    def width(self):
        return self._width

    def shape(self):
        return Shape(self.width)

    def _lhs_signals(self):
        return SignalSet((self,))

    def _rhs_signals(self):
        return SignalSet((self,))

    def _ioports(self):
        return {self}

    def __repr__(self):
        return f"(io-port {self.name})"

    def __getitem__(self, key):
        if isinstance(key, int):
            if key not in range(-self.width, self.width):
                raise IndexError(f"Index {key} is out of bounds for a {self.width}-bit I/O port")
            if key < 0:
                key += self.width
            return IOSlice(self, key, key + 1)
        elif isinstance(key, slice):
            start, stop, step = key.indices(self.width)
            if step != 1:
                raise NotImplementedError("I/O port slicing with step is not supported")
            return IOSlice(self, start, stop)
        else:
            raise TypeError(f"Cannot index I/O port with {key!r}")

    def __hash__(self):
        return hash((self._width, self.name, tuple(sorted(self.attrs.items())), self.metadata))


class IOSlice(Value):
    """An I/O port slice.

    An I/O port slice represents a portion of an I/O port.
    """

    def __init__(self, port, start, stop, *, src_loc_at=0):
        super().__init__(src_loc_at=src_loc_at)
        if not isinstance(start, int):
            raise TypeError(f"I/O slice start must be an integer, not {start!r}")
        if not isinstance(stop, int):
            raise TypeError(f"I/O slice stop must be an integer, not {stop!r}")
        if start < 0:
            raise IndexError(f"I/O slice start {start} must be non-negative")
        if start > stop:
            raise IndexError(f"I/O slice start {start} must be less than slice stop {stop}")
        if stop > port.width:
            raise IndexError(f"I/O slice stop {stop} is out of bounds for a {port.width}-bit I/O port")
        self._port = port
        self._start = start
